import math

class Solution:
    def commonFactors(self, a: int, b: int) -> int:
        g = math.gcd(a, b)
        cnt = 0
        d = 1
        while d * d <= g:
            if g % d == 0:
                cnt += 1 if d * d == g else 2
            d += 1
        return cnt

