class Solution {
public:
    int commonFactors(int a, int b) {
        int g = std::gcd(a, b);
        int cnt = 0;
        for (long long d = 1; d * d <= g; ++d)
            if (g % d == 0) cnt += (d * d == g) ? 1 : 2;
        return cnt;
    }
};

