class Solution {
    public int commonFactors(int a, int b) {
        int g = gcd(a, b), cnt = 0;
        for (int d = 1; (long) d * d <= g; ++d)
            if (g % d == 0) cnt += (d * d == g) ? 1 : 2;
        return cnt;
    }

    private int gcd(int x, int y) {
        return y == 0 ? x : gcd(y, x % y);
    }
}

